class Solution {
    long long sumSegment(long long cnt, long long v) {
        // Sum of a segment of length cnt with peak v at one end,
        // decreasing by 1 per step, clamped at 1.
        if (v >= cnt) {
            // Strictly decreasing: v, v-1, ..., v-cnt+1
            return (2 * v - cnt + 1) * cnt / 2;
        } else {
            // Decreasing to 1, then flat at 1: v, v-1, ..., 1, 1, ..., 1
            return v * (v + 1) / 2 + (cnt - v);
        }
    }
public:
    int maxValue(int n, int index, int maxSum) {
        long long lo = 1, hi = maxSum;
        while (lo < hi) {
            long long mid = (lo + hi + 1) / 2;
            long long leftLen = index + 1;
            long long rightLen = (long long)n - index;
            long long total = sumSegment(leftLen, mid) + sumSegment(rightLen, mid) - mid;
            if (total <= maxSum) {
                lo = mid;
            } else {
                hi = mid - 1;
            }
        }
        return (int)lo;
    }
};
